-- and the "Ask about this report" conversation. Owner-only.
create table public.reports (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  assess_run_id text not null,
  research_run_id text,
  drkg_run_id text,
  patient_id text,
  title text not null,
  summary text,
  drugs jsonb not null default '[]'::jsonb,   -- compact ranking: rank, name, verdict, score, headline
  report jsonb not null,                      -- the backend's full DrugReport
  pdf_path text,                              -- object in the private "reports" bucket: <user_id>/<assess_run_id>.pdf
  chat jsonb not null default '[]'::jsonb,    -- the report chat's turns, saved after each answer
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, assess_run_id)
);

create index reports_user_created_idx on public.reports (user_id, created_at desc);

alter table public.reports enable row level security;

create policy "reports: owner reads" on public.reports for select to authenticated
  using ((select auth.uid()) = user_id);
create policy "reports: owner inserts" on public.reports for insert to authenticated
  with check ((select auth.uid()) = user_id);
create policy "reports: owner updates" on public.reports for update to authenticated
  using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy "reports: owner deletes" on public.reports for delete to authenticated
  using ((select auth.uid()) = user_id);

create function public.reports_touch() returns trigger language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  return new;
end $$;
create trigger reports_touch before update on public.reports for each row execute function public.reports_touch();

-- PDFs: private bucket, one folder per user.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('reports', 'reports', false, 20971520, array['application/pdf']);

create policy "report pdfs: owner reads" on storage.objects for select to authenticated
