create policy "report pdfs: owner replaces" on storage.objects for update to authenticated
  using (bucket_id = 'reports' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "report pdfs: owner deletes" on storage.objects for delete to authenticated
