import { useEffect, useState } from 'react'
import { ExternalLink, FileText, RotateCcw } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { useAuth } from '@/lib/auth'
import { listReports, pdfLink, type SavedReport } from '@/lib/reports-db'
import { useRun } from '@/lib/run-store'
import { useGo } from './pieces'

const VERDICT: Record<string, string> = {
  strong_candidate: 'Strong candidate',
  worth_discussing: 'Worth discussing',
  use_with_caution: 'Use with caution',
  not_recommended: 'Not recommended',
}

const when = (iso: string) => new Intl.DateTimeFormat('en-CA', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(iso))

/** Live reports saved to Supabase (lib/reports-db.ts): the signed-in user's, from any machine. */
export function SavedReports() {
  const { user, configured } = useAuth()
  const { reopen, reportSave } = useRun()
  const go = useGo()
  const [reports, setReports] = useState<SavedReport[] | null>(null)
  const [error, setError] = useState<string | null>(null)

  // Refetch after a new report is saved, so it shows up without a reload.
  useEffect(() => {
    let alive = true
    listReports().then((r) => alive && setReports(r))
    return () => {
      alive = false
    }
  }, [user?.id, reportSave.status])

  if (!configured) return null
  if (!user) return <p className="text-sm text-muted-foreground">Sign in to keep live reports and their chats across sessions and machines.</p>

  async function openPdf(path: string) {
    setError(null)
    const link = await pdfLink(path)
    if (link) window.open(link, '_blank', 'noopener')
    else setError('Couldn’t open that PDF. Try again in a moment.')
  }

  return (
    <section aria-labelledby="saved-reports" className="space-y-3">
      <h2 id="saved-reports" className="text-lg font-normal">Saved reports</h2>
      {error ? <p role="alert" className="text-sm text-destructive">{error}</p> : null}
      {reports === null ? (
        <p className="text-sm text-muted-foreground">Loading…</p>
      ) : reports.length === 0 ? (
        <p className="text-sm text-muted-foreground">No saved reports yet. Finished live runs are saved here automatically.</p>
      ) : (
        <ul className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
          {reports.map((r) => {
            const top = r.drugs[0]
            return (
              <li key={r.id} className="flex flex-col gap-3 rounded-xl bg-card p-4 ring-1 ring-border backdrop-blur-md">
                <div className="min-w-0">
                  <p className="flex items-center gap-1.5 font-medium">
                    <FileText className="size-3.5 shrink-0 text-muted-foreground" aria-hidden />
                    <span className="truncate">{r.title}</span>
                  </p>
                  <p className="text-xs text-muted-foreground tabular-nums">{when(r.created_at)} · {r.assess_run_id}</p>
                </div>
                {top ? (
                  <p className="text-sm">
                    Top: <span className="font-medium">{top.name}</span>
                    <span className="text-muted-foreground"> · {VERDICT[top.verdict] ?? top.verdict}{top.score != null ? ` · ${top.score}/100` : ''}</span>
                  </p>
                ) : null}
                <div className="mt-auto flex flex-wrap gap-2">
                  {r.pdf_path ? (
