import { createContext, useCallback, useContext, useEffect, useState, type ReactNode } from 'react'
import { useAuth } from './auth'
import { saveTestReport } from './reports-db'
import { useRun } from './run-store'
import { TEST_ORIGIN, TEST_URL, buildTestPdf, parsePayload, score, summaryLine, testId, type TestResult } from './take-home'

/**
 * Receives take-home test results while the user is anywhere in the app: the test window
 * posts them to the window that opened it. Mounted once, inside RunProvider (Home.tsx).
 */

export type TakeHomeStatus = 'idle' | 'waiting' | 'saving' | 'saved' | 'off' | 'error'
type Received = { id: string; name: string; completedAt: string; results: TestResult[] }

type Store = {
  status: TakeHomeStatus
  message: string | null
  last: Received | null
  /** Open the test in its own window, so it can send its results back here. */
  openTest: () => void
  /** The fallback: the results file the test offers when this tab wasn't there to receive. */
  importFile: (file: File) => Promise<void>
}

const Ctx = createContext<Store | null>(null)

export function TakeHomeProvider({ children }: { children: ReactNode }) {
  const { caseFile } = useRun()
  const { user } = useAuth()
  const [status, setStatus] = useState<TakeHomeStatus>('idle')
  const [message, setMessage] = useState<string | null>(null)
  const [last, setLast] = useState<Received | null>(null)

  // Whose results these are: the uploaded case's patient, else the signed-in user.
  const meta = user?.user_metadata ?? {}
  const name = caseFile?.patient.label || meta.full_name || meta.name || user?.email || 'Participant'

  const receive = useCallback(
    async (raw: unknown) => {
      const payload = parsePayload(raw)
      if (!payload) {
        setStatus('error')
        setMessage('That isn’t a take-home test results file.')
        return
      }
      const results = score(payload)
      const id = testId(payload.completedAt)
      setLast({ id, name, completedAt: payload.completedAt, results })
      setStatus('saving')
      setMessage(null)
      const pdf = buildTestPdf(results, { name, id, completedAt: payload.completedAt })
      const saved = await saveTestReport({ id, name, summary: summaryLine(results), payload, pdf, completedAt: payload.completedAt })
      setStatus(saved.status)
      setMessage(saved.status === 'error' ? saved.message : null)
    },
    [name],
  )

  useEffect(() => {
    const onMessage = (e: MessageEvent) => {
      if (e.origin !== TEST_ORIGIN || (e.data as { kind?: string })?.kind !== 'addo-take-home-v1') return
      void receive(e.data)
    }
    window.addEventListener('message', onMessage)
    return () => window.removeEventListener('message', onMessage)
  }, [receive])

  const openTest = useCallback(() => {
    // Not noopener: the test needs window.opener to send its results back to this origin.
    window.open(`${TEST_URL}/?return=${encodeURIComponent(window.location.origin)}`, 'addo-take-home')
    setStatus('waiting')
    setMessage(null)
  }, [])

  const importFile = useCallback(
    async (file: File) => {
      try {
        await receive(JSON.parse(await file.text()))
      } catch {
        setStatus('error')
        setMessage('Couldn’t read that file. Choose the results file the test offered at the end.')
      }
    },
    [receive],
  )

  return <Ctx.Provider value={{ status, message, last, openTest, importFile }}>{children}</Ctx.Provider>
}

export function useTakeHome() {
  const ctx = useContext(Ctx)
  if (!ctx) throw new Error('useTakeHome must be used inside <TakeHomeProvider>')
  return ctx
}

