-- Take-home test links. The web app (signed in) creates an invite; its code goes in the test
-- link. The test app, which has no user session, submits its results with that code through
-- submit_take_home(), which files them as a report for the invite's owner. One use, 7 days.
create table public.take_home_invites (
  code uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  participant_name text not null default 'Participant' check (char_length(participant_name) <= 120),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '7 days',
  used_at timestamptz,
  report_id uuid references public.reports (id) on delete set null
);

create index take_home_invites_user_idx on public.take_home_invites (user_id, created_at desc);

alter table public.take_home_invites enable row level security;

create policy "invites: owner reads" on public.take_home_invites for select to authenticated
  using ((select auth.uid()) = user_id);
create policy "invites: owner creates" on public.take_home_invites for insert to authenticated
  with check ((select auth.uid()) = user_id);
create policy "invites: owner deletes" on public.take_home_invites for delete to authenticated
  using ((select auth.uid()) = user_id);

-- Callable without a session (the test app), but only does one thing: with a valid, unused,
-- unexpired code, store one results payload as that code owner's take-home report.
create function public.submit_take_home(p_code uuid, p_results jsonb) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  inv public.take_home_invites;
  rid uuid;
begin
  select * into inv from public.take_home_invites where code = p_code for update;
  if inv.code is null or inv.used_at is not null or inv.expires_at < now() then
    raise exception 'This test link is invalid, already used or expired.' using errcode = '22023';
  end if;
  if p_results ->> 'kind' is distinct from 'addo-take-home-v1' or jsonb_typeof(p_results -> 'tests') is distinct from 'object'
     or octet_length(p_results::text) > 262144 then
    raise exception 'Not a take-home test results payload.' using errcode = '22023';
  end if;
  insert into public.reports (user_id, kind, assess_run_id, title, report)
  values (
    inv.user_id,
    'take_home_test',
    't' || to_char(now() at time zone 'utc', 'YYYYMMDD-HH24MISS') || '-' || left(replace(p_code::text, '-', ''), 6),
    'Take-home test results · ' || inv.participant_name,
    p_results || jsonb_build_object('patient', jsonb_build_object('name', inv.participant_name))
  )
  returning id into rid;
  update public.take_home_invites set used_at = now(), report_id = rid where code = p_code;
  return rid;
end $$;

revoke all on function public.submit_take_home(uuid, jsonb) from public;
grant execute on function public.submit_take_home(uuid, jsonb) to anon, authenticated;

begin;
create temp table t_out (step text, ok text) on commit drop;
grant all on t_out to anon, authenticated;
-- 1. signed-in user creates an invite
select set_config('request.jwt.claims', json_build_object('sub', (select id from auth.users limit 1)::text, 'role', 'authenticated')::text, true);
set local role authenticated;
insert into public.take_home_invites (participant_name) values ('Alex Chen');
create temp table t_code on commit drop as select code from public.take_home_invites order by created_at desc limit 1;
grant select on t_code to anon;
-- 2. anonymous caller (the test app) submits with the code
reset role;
select set_config('request.jwt.claims', '{"role":"anon"}', true);
set local role anon;
insert into t_out select 'anon submit returns report id', (public.submit_take_home((select code from t_code), '{"kind":"addo-take-home-v1","completedAt":"2026-11-08T12:00:00Z","tests":{"line":{"shapes":[]}}}'::jsonb) is not null)::text;
-- 3. reuse must fail
do $$ begin perform public.submit_take_home((select code from t_code), '{"kind":"addo-take-home-v1","tests":{}}'::jsonb); insert into t_out values ('reuse rejected', 'NO - accepted!'); exception when others then insert into t_out values ('reuse rejected', 'yes: ' || sqlerrm); end $$;
-- 4. unknown code must fail
do $$ begin perform public.submit_take_home(gen_random_uuid(), '{"kind":"addo-take-home-v1","tests":{}}'::jsonb); insert into t_out values ('unknown code rejected', 'NO'); exception when others then insert into t_out values ('unknown code rejected', 'yes'); end $$;
-- 5. anon can't read reports or invites directly
insert into t_out select 'anon sees reports', count(*)::text from public.reports;
insert into t_out select 'anon sees invites', count(*)::text from public.take_home_invites;
-- 6. the owner sees the filed report with the participant name
reset role;
select set_config('request.jwt.claims', json_build_object('sub', (select id from auth.users limit 1)::text, 'role', 'authenticated')::text, true);
set local role authenticated;
insert into t_out select 'owner sees test report', count(*)::text || ' / name=' || max(report->'patient'->>'name') from public.reports where kind = 'take_home_test';
insert into t_out select 'invite marked used', (used_at is not null and report_id is not null)::text from public.take_home_invites where code = (select code from t_code);
reset role;
select * from t_out;
rollback;

