/**
 * Save take-home test results (lib/take-home.ts): the PDF to storage and a row of kind
 * 'take_home_test'. Idempotent per test id, so receiving the same results twice is harmless.
 */
export async function saveTestReport(row: { id: string; name: string; summary: string; payload: unknown; pdf: Blob; completedAt: string }): Promise<
  { status: 'saved' | 'off' } | { status: 'error'; message: string }
> {
  const uid = await userId()
  if (!supabase || !uid) return { status: 'off' }
  const pdfPath = `${uid}/${row.id}.pdf`
  const up = await supabase.storage.from('reports').upload(pdfPath, row.pdf, { contentType: 'application/pdf', upsert: true })
  if (up.error) return { status: 'error', message: `PDF not saved: ${up.error.message}` }
  const { error } = await supabase.from('reports').upsert(
    {
      user_id: uid,
      kind: 'take_home_test',
      assess_run_id: row.id,
      title: `Take-home test results · ${row.name}`,
      summary: row.summary,
      // report.patient keeps the Reports page's naming logic the same for both kinds.
      report: { ...(row.payload as object), patient: { name: row.name } },
      pdf_path: pdfPath,
      created_at: row.completedAt,
    },
    { onConflict: 'user_id,assess_run_id' },
  )
  return error ? { status: 'error', message: `Results not saved: ${error.message}` } : { status: 'saved' }
}

