        if self.path!="/photo" or self.headers.get("Host")!=URL[7:] or self.headers.get("Origin")!=URL:
            return self.send_error(403)
        try:
            size=int(self.headers.get("Content-Length",0))
            if not 0<size<=8_000_000:
